// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Controlled_Outcome_Derivation_governor_process_controlled_outcome_derivation_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation)
  }

  /** helper function to set the values of all input ports.
   * @param selected_phase payload for data port selected_phase
   */
  def put_concrete_inputs(selected_phase : Drone_Lifecycle_Governor.Lifecycle_Phase.Type): Unit = {
    put_selected_phase(selected_phase)
  }


  /** helper function to check Controlled_Outcome_Derivation_governor_process_controlled_outcome_derivation's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param lifecycle_actuation method that will be called with the value of the outgoing data
   *        port 'lifecycle_actuation'.
   */
  def check_concrete_output(lifecycle_actuation: Drone_Lifecycle_Governor.Lifecycle_Actuation => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val lifecycle_actuationValue: Drone_Lifecycle_Governor.Lifecycle_Actuation = get_lifecycle_actuation().get
    if(!lifecycle_actuation(lifecycle_actuationValue)) {
      testFailures = testFailures :+ st"'lifecycle_actuation' did not match expected: value of the outgoing data port is ${lifecycle_actuationValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_selected_phase(value : Drone_Lifecycle_Governor.Lifecycle_Phase.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation.operational_api.selected_phase_Id, Drone_Lifecycle_Governor.Lifecycle_Phase_Payload(value))
  }

  // getter for out DataPort
  def get_lifecycle_actuation(): Option[Drone_Lifecycle_Governor.Lifecycle_Actuation] = {
    val value: Option[Drone_Lifecycle_Governor.Lifecycle_Actuation] = get_lifecycle_actuation_payload() match {
      case Some(Drone_Lifecycle_Governor.Lifecycle_Actuation_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port lifecycle_actuation.  Expecting 'Drone_Lifecycle_Governor.Lifecycle_Actuation_Payload' but received ${v}")
      case _ => None[Drone_Lifecycle_Governor.Lifecycle_Actuation]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_lifecycle_actuation_payload(): Option[Drone_Lifecycle_Governor.Lifecycle_Actuation_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Drone_Lifecycle_Governor_System_Instance_governor_process_controlled_outcome_derivation.initialization_api.lifecycle_actuation_Id).asInstanceOf[Option[Drone_Lifecycle_Governor.Lifecycle_Actuation_Payload]]
  }

}
